/* ------------------------------------------------------------------ */
/*  Автоматический разбор словаря «Русское словесное ударение»        */
/*  М.В. Зарва — заголовочные слова + позиция ударной гласной.        */
/*  Слоги для игры строятся на лету функцией syllabify().             */
/* ------------------------------------------------------------------ */
const VOWELS = "аеёиоуыэюя";

function syllabify(word) {
  const vp = [];
  for (let i = 0; i < word.length; i++) if (VOWELS.includes(word[i])) vp.push(i);
  if (vp.length === 0) return [word];
  const starts = [0];
  for (let k = 0; k < vp.length - 1; k++) {
    const v1 = vp[k], v2 = vp[k + 1];
    const clusterLen = v2 - v1 - 1;
    starts.push(clusterLen <= 1 ? v1 + 1 : v1 + 2);
  }
  return starts.map((s, i) => word.slice(s, i + 1 < starts.length ? starts[i + 1] : word.length));
}

function buildEntry(word, stressPos, note = "") {
  const syl = syllabify(word);
  let acc = 0, idx = 0;
  for (let i = 0; i < syl.length; i++) {
    if (stressPos >= acc && stressPos < acc + syl[i].length) { idx = i; break; }
    acc += syl[i].length;
  }
  return { w: syl, s: idx, note };
}

