function shuffled(arr) {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}
function wordPlain(entry) { return entry.w.join(""); }
/* Перемешивает варианты ответа (opts) в вопросах теста на грамматику, чтобы верный ответ не был всегда первым */
function shuffleEntryOpts(entry) {
  if (!entry.opts) return entry;
  const order = shuffled(entry.opts.map((_, i) => i));
  const opts = order.map((i) => entry.opts[i]);
  const c = order.indexOf(entry.c);
  return { ...entry, opts, c };
}

const INK = "#14161B", PANEL = "#1D2027", BORDER = "#2A2E37", CREAM = "#F6F1E4";
const AMBER = "#E7A93C", CORAL = "#D9662E", GREEN = "#5FA777", RED = "#D6544A";
const MUTED = "#9CA0AA", FAINT = "#6B6F79";

/* Слово с ударением по точной позиции буквы (для словаря Зарвы, без слогов) */
function StressedWord({ plain, pos, size = "text-base", tone = "light" }) {
  const color = tone === "dark" ? "#1E1B16" : CREAM;
  return (
    <span className={`${size} font-semibold tracking-tight`} style={{ fontFamily: "'Manrope', sans-serif", color }}>
      {[...plain].map((ch, i) => (
        <span key={i} style={{ position: "relative", display: "inline-block" }}>
          {i === pos && (
            <span aria-hidden="true" style={{ position: "absolute", top: -11, left: "50%", transform: "translateX(-50%) rotate(8deg)", fontSize: "0.65em", color: AMBER, fontWeight: 800 }}>´</span>
          )}
          <span style={{ color: i === pos ? AMBER : "inherit" }}>{ch}</span>
        </span>
      ))}
    </span>
  );
}

function AccentWord({ entry, size = "text-lg", tone = "dark" }) {
  const color = tone === "dark" ? "#1E1B16" : CREAM;
  return (
    <span className={`${size} font-semibold tracking-tight`} style={{ fontFamily: "'Manrope', sans-serif", color }}>
      {entry.w.map((syl, i) => (
        <span key={i} style={{ position: "relative", display: "inline-block" }}>
          {i === entry.s && (
            <span aria-hidden="true" style={{ position: "absolute", top: -13, left: "50%", transform: "translateX(-50%) rotate(8deg)", fontSize: "0.7em", color: AMBER, fontWeight: 800 }}>´</span>
          )}
          <span style={{ color: i === entry.s ? AMBER : "inherit" }}>{syl}</span>
        </span>
      ))}
    </span>
  );
}

function OnAirDot({ active }) {
  return (
    <span className="inline-flex items-center gap-1.5">
      <span className="inline-block rounded-full" style={{ width: 7, height: 7, background: active ? AMBER : "#4A4E58", boxShadow: active ? "0 0 0 3px rgba(231,169,60,0.25)" : "none", animation: active ? "govorunPulse 1.6s ease-in-out infinite" : "none" }} />
      <span className="text-[10px] uppercase tracking-[0.18em]" style={{ color: MUTED, fontFamily: "'Manrope', sans-serif" }}>{active ? "в эфире" : "офлайн"}</span>
    </span>
  );
}

