function ResultScreen({ score, total, pass, level, perfectStreak, campaignActive, campaignMistakes, campaignOutcome, offerPending, motivation, onContinue, onAcceptOffer, onDeclineOffer, onRestartCampaign }) {
  const passed = score >= pass;
  const perfect = score === total;
  useEffect(() => { if (perfect && !campaignOutcome) speakPerfect(); }, [perfect, campaignOutcome]);

  if (campaignOutcome === "won") {
    return (
      <div className="flex-1 flex flex-col px-5 pt-4 pb-10">
        <div className="text-center mt-6 mb-6 govorun-pop">
          <GovorunBird size={110} mood="love" />
          <h2 className="mt-4" style={{ fontFamily: "'Playfair Display', serif", color: CREAM, fontSize: 28, fontWeight: 800 }}>Вы — магистр знаний по речи!</h2>
          <p className="mt-2 text-base leading-relaxed" style={{ color: MUTED }}>Все {TOTAL_LEVELS} уровней пройдены, ошибок — {campaignMistakes} из {MAX_CAMPAIGN_MISTAKES} допустимых. Полный видеокурс «Говори красиво» — ваш.</p>
        </div>
        <div className="rounded-2xl p-5" style={{ background: PANEL, border: `1px solid ${AMBER}` }}>
          <p className="text-base font-semibold mb-3" style={{ color: CREAM }}>Напишите Талгату в WhatsApp, чтобы получить курс:</p>
          <button onClick={() => window.open(MASTER_WHATSAPP_URL, "_blank")} className="w-full flex items-center justify-center gap-2 rounded-xl py-4 font-bold text-base" style={{ background: AMBER, color: INK }}>
            <Mic2 size={18} /> «Я магистр знаний по речи!»
          </button>
        </div>
        <button onClick={onRestartCampaign} className="mt-5 w-full flex items-center justify-center gap-2 rounded-2xl py-4 font-bold text-base" style={{ background: "#2A2E37", color: CREAM }}>
          <RotateCcw size={17} /> Пройти путь заново
        </button>
      </div>
    );
  }

  if (campaignOutcome === "failed") {
    return (
      <div className="flex-1 flex flex-col px-5 pt-4 pb-10">
        <div className="text-center mt-6 mb-6 govorun-pop">
          <GovorunBird size={90} mood="panic" />
          <h2 className="mt-4" style={{ fontFamily: "'Playfair Display', serif", color: CREAM, fontSize: 26, fontWeight: 800 }}>Не в этот раз</h2>
          <p className="mt-2 text-base leading-relaxed" style={{ color: MUTED }}>Ошибок набралось больше {MAX_CAMPAIGN_MISTAKES} — курс за этот забег не открылся. Но вы дошли до уровня {level} из {TOTAL_LEVELS} — это уже отлично. Попробуйте ещё раз!</p>
        </div>
        <button onClick={onRestartCampaign} className="w-full flex items-center justify-center gap-2 rounded-2xl py-4.5 font-bold text-lg" style={{ background: AMBER, color: INK }}>
          <RotateCcw size={19} /> Начать заново
        </button>
      </div>
    );
  }

  return (
    <div className="flex-1 flex flex-col px-5 pt-4 pb-10">
      <div className="text-center mt-4 mb-6">
        <p className="text-sm uppercase tracking-[0.14em] font-semibold mb-2" style={{ color: FAINT }}>уровень {level} · результат</p>
        <div style={{ fontFamily: "'Playfair Display', serif", fontSize: 60, fontWeight: 800, color: CREAM }}>
          {score}<span style={{ color: "#5B5F69", fontSize: 30 }}>/{total}</span>
        </div>
        {campaignActive && (
          <p className="text-sm mt-2 font-semibold" style={{ color: AMBER }}>ошибок за поход: {campaignMistakes} из {MAX_CAMPAIGN_MISTAKES}</p>
        )}
      </div>

      {motivation && (
        <div className="flex items-center gap-3 rounded-2xl p-4 mb-4" style={{ background: "rgba(231,169,60,0.08)", border: `1px solid ${BORDER}` }}>
          <GovorunBird size={34} mood={perfect ? "love" : "normal"} />
          <p className="text-sm font-semibold" style={{ color: CREAM }}>{motivation}</p>
        </div>
      )}

      {perfect && !offerPending && (
        <div className="govorun-pop flex items-center gap-3 rounded-2xl p-4 mb-4" style={{ background: "rgba(231,169,60,0.12)", border: `1px solid ${AMBER}` }}>
          <Sparkles size={20} color={AMBER} />
          <p className="text-base font-bold" style={{ color: AMBER }}>Уровень пройден без единой ошибки!</p>
        </div>
      )}

      {passed ? (
        <div className="rounded-2xl p-5 govorun-pop" style={{ background: PANEL, border: `1px solid ${AMBER}` }}>
          <div className="flex items-center gap-2 mb-2">
            <Sparkles size={18} color={AMBER} />
            <span className="text-base font-bold" style={{ color: AMBER }}>Урок открыт</span>
          </div>
          <p className="text-base font-semibold mb-1" style={{ color: CREAM }}>{REWARD_VIDEO.title}</p>
          <p className="text-sm mb-4" style={{ color: MUTED }}>курс «Говори красиво»</p>
          <button className="w-full flex items-center justify-center gap-2 rounded-xl py-3.5 font-bold text-base" style={{ background: AMBER, color: INK }} onClick={() => window.open(REWARD_VIDEO.url, "_blank")}>
            <Play size={17} fill={INK} /> Смотреть видео
          </button>
        </div>
      ) : (
        <div className="rounded-2xl p-5" style={{ background: PANEL, border: `1px solid ${BORDER}` }}>
          <p className="text-base font-semibold mb-1" style={{ color: CREAM }}>Ещё чуть-чуть до урока</p>
          <p className="text-sm" style={{ color: MUTED }}>Нужно {pass} из {total} верных. Слова и фразы каждый раз новые — пробуйте ещё раз.</p>
        </div>
      )}

      {offerPending ? (
        <div className="govorun-pop mt-5 rounded-2xl p-5" style={{ background: "rgba(231,169,60,0.1)", border: `1px solid ${AMBER}` }}>
          <div className="flex items-center gap-2 mb-2">
            <Award size={18} color={AMBER} />
            <span className="text-base font-bold" style={{ color: AMBER }}>3 уровня без единой ошибки!</span>
          </div>
          <p className="text-sm leading-relaxed mb-4" style={{ color: CREAM }}>Хотите получить полный видеокурс «Говори красиво»? Пройдите все {TOTAL_LEVELS} уровней, сделав максимум {MAX_CAMPAIGN_MISTAKES} ошибок — и получите онлайн-курс бесплатно!</p>
          <div className="flex flex-col gap-2">
            <button onClick={onAcceptOffer} className="w-full flex items-center justify-center gap-2 rounded-xl py-4 font-bold text-base" style={{ background: AMBER, color: INK }}>
              Хочу!
            </button>
            <button onClick={onDeclineOffer} className="w-full flex items-center justify-center gap-2 rounded-xl py-3 font-semibold text-sm" style={{ background: "transparent", color: MUTED }}>
              Не сейчас
            </button>
          </div>
        </div>
      ) : (
        <button onClick={onContinue} className="mt-5 w-full flex items-center justify-center gap-2 rounded-2xl py-4 font-bold text-base" style={{ background: "#2A2E37", color: CREAM }}>
          <ChevronRight size={18} /> {campaignActive ? `Уровень ${level + 1} из ${TOTAL_LEVELS}` : "Продолжить"}
        </button>
      )}
    </div>
  );
}

