export default function Govorun() {
  const [tab, setTab] = useState("home"); // home | accent | grammar | dict | about
  const [query, setQuery] = useState("");

  const accentTest = useTestEngine("accent", ACCENT_POOL, ACCENT_TOTAL, 60);
  const grammarTest = useTestEngine("grammar", GRAMMAR_ALL, GRAMMAR_TOTAL, 90);

  const dictResult = useMemo(() => {
    const q = query.trim().toLowerCase();
    if (!q) return { list: [], total: 0, capped: false, isDefault: true };
    const matches = ZARVA_ENTRIES.filter((entry) => entry.some(([w]) => w.includes(q)));
    matches.sort((a, b) => a[0][0].localeCompare(b[0][0], "ru"));
    return { list: matches.slice(0, 60), total: matches.length, capped: matches.length > 60, isDefault: false };
  }, [query]);

  const anyGameActive = (tab === "accent" && accentTest.phase === "game") || (tab === "grammar" && grammarTest.phase === "game");

  const goHome = () => setTab("home");

  return (
    <div className="min-h-screen w-full flex justify-center" style={{ background: INK, fontFamily: "'Manrope', sans-serif" }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Playfair+Display:wght@700;800;900&family=Manrope:wght@400;500;600;700;800&display=swap');
        @keyframes govorunPulse { 0%,100% { opacity:1 } 50% { opacity:.35 } }
        @keyframes govorunShake { 0%,100% { transform: translateX(0) } 25% { transform: translateX(-6px) } 75% { transform: translateX(6px) } }
        @keyframes govorunPop { 0% { transform: scale(.85); opacity:0 } 100% { transform: scale(1); opacity:1 } }
        @keyframes govorunFloat { 0%,100% { transform: translateY(0) } 50% { transform: translateY(-6px) } }
        .govorun-shake { animation: govorunShake .32s ease; }
        .govorun-pop { animation: govorunPop .28s ease; }
        .govorun-float { animation: govorunFloat 3.2s ease-in-out infinite; }
        .govorun-scroll::-webkit-scrollbar { width: 4px; }
        .govorun-scroll::-webkit-scrollbar-thumb { background: #33363F; border-radius: 4px; }
        @keyframes govorunHeartRise { 0% { transform: translateY(30vh) scale(.6); opacity:0 } 8% { opacity:1 } 100% { transform: translateY(-55vh) scale(1.2); opacity:0 } }
        .govorun-heart { position:absolute; bottom:38%; animation: govorunHeartRise 3s ease-out forwards; }
        @keyframes govorunLovePop { 0% { transform: scale(.5); opacity:0 } 15% { transform: scale(1.18); opacity:1 } 85% { transform: scale(1); opacity:1 } 100% { opacity:0; transform: scale(.92) } }
        .govorun-bird-love { animation: govorunLovePop 3.1s ease; }
        @keyframes govorunRunAround {
          0% { transform: translate(-110px, 15px) rotate(-8deg); }
          9% { transform: translate(95px, -45px) rotate(11deg); }
          18% { transform: translate(-80px, -75px) rotate(-15deg); }
          27% { transform: translate(115px, 5px) rotate(13deg); }
          36% { transform: translate(-95px, 55px) rotate(-11deg); }
          45% { transform: translate(65px, -25px) rotate(9deg); }
          54% { transform: translate(-100px, -20px) rotate(-13deg); }
          63% { transform: translate(90px, 40px) rotate(10deg); }
          72% { transform: translate(-60px, -55px) rotate(-9deg); }
          81% { transform: translate(70px, -10px) rotate(8deg); }
          90% { transform: translate(-40px, 10px) rotate(-6deg); }
          100% { transform: translate(0,0) rotate(0deg); opacity:0; }
        }
        .govorun-bird-panic { animation: govorunRunAround 3.1s ease-in-out; }
      `}</style>

      <div className="w-full max-w-md min-h-screen flex flex-col" style={{ background: INK }}>
        {/* Header */}
        <header className="flex items-center justify-between px-5 pt-6 pb-4">
          {tab === "home" ? (
            <Logo />
          ) : (
            <button onClick={goHome} className="flex items-center gap-1 text-base font-semibold" style={{ color: MUTED }}>
              <ChevronLeft size={19} /> Говорун
            </button>
          )}
          <OnAirDot active={anyGameActive} />
        </header>

        {/* ============ ГЛАВНАЯ ============ */}
        {tab === "home" && (
          <div className="flex-1 flex flex-col px-6 pt-2 pb-10">
            <div className="flex-1 flex flex-col items-center justify-center text-center">
              <div className="govorun-float">
                <GovorunBird size={140} />
              </div>
              <h1 className="mt-5" style={{ fontFamily: "'Playfair Display', serif", color: CREAM, fontSize: 34, fontWeight: 800 }}>Говорун</h1>
              <p className="mt-2 text-base max-w-[280px]" style={{ color: MUTED }}>
                Играй в слова, проверяй ударения и говори без ошибок — вместе с Талгатом Байгужиновым
              </p>
            </div>

            <div className="flex flex-col gap-3 mt-6">
              {MENU_ITEMS.map((item) => {
                const Icon = item.icon;
                return (
                  <button
                    key={item.id}
                    onClick={() => setTab(item.id)}
                    className="w-full flex items-center gap-4 rounded-2xl px-4 py-4 text-left"
                    style={{ background: PANEL, border: `1px solid ${BORDER}` }}
                  >
                    <span className="w-12 h-12 rounded-xl flex items-center justify-center flex-shrink-0" style={{ background: "rgba(231,169,60,0.14)" }}>
                      <Icon size={22} color={AMBER} />
                    </span>
                    <span className="flex-1">
                      <span className="block text-base font-bold" style={{ color: CREAM }}>{item.label}</span>
                      <span className="block text-sm mt-0.5" style={{ color: FAINT }}>{item.desc}</span>
                    </span>
                    <ChevronRight size={19} color={FAINT} />
                  </button>
                );
              })}
            </div>
          </div>
        )}

        {/* ============ УДАРЕНИЯ ============ */}
        {tab === "accent" && (
          <TestTab
            engine={accentTest}
            renderer="syllables"
            total={ACCENT_TOTAL}
            pass={ACCENT_PASS}
            intro={{
              title: <>Отметь ударный слог.<br /><span style={{ color: AMBER }}>Выиграй урок.</span></>,
              text: <>{ACCENT_TOTAL} слов — после каждого ответа объясняем, что оно значит. Наберите {ACCENT_PASS} из {ACCENT_TOTAL} — и получите бесплатный видеоурок от Талгата.</>,
              sampleEntry: ACCENT_L2[0],
            }}
          />
        )}

        {/* ============ ГРАММАТИКА ============ */}
        {tab === "grammar" && (
          <TestTab
            engine={grammarTest}
            renderer="phrase"
            total={GRAMMAR_TOTAL}
            pass={GRAMMAR_PASS}
            intro={{
              title: <>Найди речевую ошибку.<br /><span style={{ color: AMBER }}>Говори без запинки.</span></>,
              text: <>{GRAMMAR_TOTAL} вопросов на падежи, предлоги и трудные формы — «носков» или «носок», «оплатить» или «оплатить за». Наберите {GRAMMAR_PASS} из {GRAMMAR_TOTAL} для видеоурока.</>,
              sampleEntry: GRAMMAR_L2[4],
            }}
          />
        )}

        {/* ============ СЛОВАРЬ ============ */}
        {tab === "dict" && (
          <div className="flex-1 flex flex-col px-5 pt-2 pb-6 overflow-hidden">
            <div className="flex items-center gap-2.5 rounded-xl px-4 py-3.5 mb-4" style={{ background: PANEL, border: `1px solid ${BORDER}` }}>
              <Search size={17} color={FAINT} />
              <input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Найти слово среди ~42000…" className="bg-transparent outline-none flex-1 text-base" style={{ color: CREAM }} />
            </div>
            {dictResult.isDefault && (
              <p className="text-sm mb-3" style={{ color: FAINT }}>начните печатать, чтобы искать по словарю «Русское словесное ударение» М.В. Зарвы</p>
            )}
            <div className="flex-1 overflow-y-auto govorun-scroll -mx-5 px-5">
              {!dictResult.isDefault && dictResult.list.length === 0 && <p className="text-base text-center mt-10" style={{ color: FAINT }}>Ничего не нашлось</p>}
              <div className="flex flex-col gap-2.5 pb-4">
                {dictResult.list.map((entry, i) => (
                  <div key={i} className="rounded-xl px-4 py-3.5 flex items-start justify-between gap-2" style={{ background: PANEL, border: `1px solid ${BORDER}` }}>
                    <div className="flex-1 min-w-0">
                      <StressedWord plain={entry[0][0]} pos={entry[0][1]} size="text-lg" tone="light" />
                      {entry.length > 1 && (
                        <p className="text-xs mt-1.5 leading-relaxed" style={{ color: FAINT }}>
                          {entry.slice(1).map(([w, p], j) => (
                            <span key={j}>
                              <StressedWord plain={w} pos={p} size="text-xs" tone="light" />
                              {j < entry.length - 2 ? ", " : ""}
                            </span>
                          ))}
                        </p>
                      )}
                    </div>
                    <button onClick={() => speakDictWord(entry[0][0], entry[0][1])} className="shrink-0 w-10 h-10 rounded-full flex items-center justify-center" style={{ background: "rgba(231,169,60,0.14)" }} aria-label="Озвучить слово">
                      <Volume2 size={17} color={AMBER} />
                    </button>
                  </div>
                ))}
                {dictResult.capped && (
                  <p className="text-center text-sm py-2" style={{ color: FAINT }}>показаны первые 60 из {dictResult.total} — уточните запрос</p>
                )}
              </div>
            </div>
          </div>
        )}

        {/* ============ ОБО МНЕ ============ */}
        {tab === "about" && <AboutTab />}
      </div>
    </div>
  );
}

/* ================================================================== */
/*  TestTab — общий контейнер для теста ударений / грамматики          */
/* ================================================================== */

function TestTab({ engine, renderer, intro, total, pass }) {
  const {
    phase, round, qIndex, score, selected, answered, pick, next, reaction, timeLeft, timeLimit,
    level, perfectStreak, campaignActive, campaignMistakes, campaignOutcome, offerPending, motivation,
    beginFresh, continueNext, acceptOffer, declineOffer,
  } = engine;
  const current = round[qIndex];

  if (phase === "home") {
    return (
      <div className="flex-1 flex flex-col px-5 pt-4 pb-10">
        <h1 className="leading-[1.15]" style={{ fontFamily: "'Playfair Display', serif", color: CREAM, fontSize: 30, fontWeight: 800 }}>{intro.title}</h1>
        <p className="mt-3 text-base leading-relaxed" style={{ color: MUTED }}>{intro.text}</p>

        <div className="mt-5 rounded-2xl p-5 govorun-pop" style={{ background: PANEL, border: `1px solid ${BORDER}` }}>
          <div className="flex items-center gap-2 mb-3">
            <Radio size={16} color={AMBER} />
            <span className="text-sm uppercase tracking-[0.14em] font-semibold" style={{ color: AMBER }}>пример вопроса</span>
          </div>
          {renderer === "syllables" ? (
            <>
              <p className="text-sm mb-2" style={{ color: FAINT }}>значение слова: <span style={{ color: CREAM, fontWeight: 600 }}>{intro.sampleEntry.note}</span></p>
              <div className="flex flex-wrap gap-2">
                {intro.sampleEntry.w.map((syl, i) => (
                  <span key={i} className="px-3.5 py-2.5 rounded-lg text-base font-semibold" style={{ background: i === intro.sampleEntry.s ? "rgba(231,169,60,0.15)" : INK, color: i === intro.sampleEntry.s ? AMBER : CREAM, border: i === intro.sampleEntry.s ? `1px solid ${AMBER}` : `1px solid ${BORDER}` }}>{syl}</span>
                ))}
              </div>
              <p className="mt-3 text-sm" style={{ color: FAINT }}>верно: <AccentWord entry={intro.sampleEntry} size="text-sm" tone="light" /></p>
            </>
          ) : (
            <>
              <p className="text-base leading-relaxed" style={{ color: CREAM }}>{intro.sampleEntry.p[0]}<span style={{ color: AMBER, fontWeight: 700 }}>{intro.sampleEntry.opts[intro.sampleEntry.c]}</span>{intro.sampleEntry.p[1]}</p>
              <p className="mt-3 text-sm" style={{ color: FAINT }}>{intro.sampleEntry.note}</p>
            </>
          )}
        </div>

        <button onClick={beginFresh} className="mt-auto w-full flex items-center justify-center gap-2 rounded-2xl py-5 font-bold text-lg mt-8" style={{ background: AMBER, color: INK }}>
          <Play size={20} fill={INK} /> Начать тест
        </button>
        <p className="text-center text-sm mt-3" style={{ color: "#5B5F69" }}>{total} вопросов · {pass} правильных — и урок ваш · на прохождение {timeLimit} сек</p>
      </div>
    );
  }

  if (phase === "game" && current) {
    const timeLow = timeLeft != null && timeLeft <= 10;
    return (
      <div className="flex-1 flex flex-col px-5 pt-2 pb-8">
        <BirdReaction state={reaction} />
        <div className="flex items-center justify-between mb-4">
          <span className="text-sm font-semibold" style={{ color: MUTED }}>уровень {level} · {score} / {total} · вопрос {qIndex + 1} из {total}</span>
        </div>
        <div className="w-full rounded-full h-1.5 mb-5" style={{ background: BORDER }}>
          <div className="h-1.5 rounded-full" style={{ width: `${((qIndex) / total) * 100}%`, background: AMBER, transition: "width .3s" }} />
        </div>

        {renderer === "syllables" ? (
          <SyllableQuestion entry={current} answered={answered} selected={selected} onPick={(i) => pick(i, i === current.s)} />
        ) : (
          <PhraseQuestion entry={current} answered={answered} selected={selected} onPick={(i) => pick(i, i === current.c)} />
        )}

        {timeLeft != null && (
          <div className="flex items-center gap-3 mb-4">
            <Timer size={16} color={timeLow ? RED : FAINT} />
            <div className="flex-1 rounded-full h-2" style={{ background: BORDER }}>
              <div className="h-2 rounded-full" style={{ width: `${Math.max(0, (timeLeft / timeLimit) * 100)}%`, background: timeLow ? RED : AMBER, transition: "width 1s linear" }} />
            </div>
            <span className="text-sm font-bold tabular-nums" style={{ color: timeLow ? RED : MUTED }}>{Math.floor(timeLeft / 60)}:{String(timeLeft % 60).padStart(2, "0")}</span>
          </div>
        )}

        {answered && (
          <button onClick={next} className="w-full flex items-center justify-center gap-1 rounded-2xl py-4 font-bold text-base" style={{ background: AMBER, color: INK }}>
            {qIndex + 1 >= round.length ? "Итоги" : "Дальше"} <ChevronRight size={18} />
          </button>
        )}
      </div>
    );
  }

  if (phase === "result") {
    return (
      <ResultScreen
        score={score} total={total} pass={pass} level={level} perfectStreak={perfectStreak}
        campaignActive={campaignActive} campaignMistakes={campaignMistakes} campaignOutcome={campaignOutcome}
        offerPending={offerPending} motivation={motivation}
        onContinue={continueNext} onAcceptOffer={acceptOffer} onDeclineOffer={declineOffer} onRestartCampaign={beginFresh}
      />
    );
  }
  return null;
}

function SyllableQuestion({ entry, answered, selected, onPick }) {
  return (
    <>
      <p className="text-sm uppercase tracking-[0.14em] mb-3 font-semibold" style={{ color: FAINT }}>где ударение?</p>
      <div className="govorun-pop rounded-2xl p-6 mb-5" style={{ background: CREAM }}>
        {entry.note && (
          <p className="text-sm text-center mb-4" style={{ color: "#8A8371" }}>значение слова: <span style={{ color: "#5B5347", fontWeight: 600 }}>{entry.note}</span></p>
        )}
        <div className="flex flex-wrap gap-2.5 justify-center">
          {entry.w.map((syl, i) => {
            const isCorrect = i === entry.s, isPicked = i === selected;
            let bg = "#EAE3D2", color = "#1E1B16", border = "1px solid transparent";
            if (answered) {
              if (isCorrect) { bg = "rgba(95,167,119,0.18)"; color = "#3E8159"; border = `1px solid ${GREEN}`; }
              else if (isPicked) { bg = "rgba(214,84,74,0.14)"; color = "#B84239"; border = `1px solid ${RED}`; }
            }
            return (
              <button key={i} onClick={() => onPick(i)} disabled={answered} className={`px-5 py-3.5 rounded-xl text-2xl font-bold ${answered && isPicked && !isCorrect ? "govorun-shake" : ""}`} style={{ background: bg, color, border }}>{syl}</button>
            );
          })}
        </div>
        {answered && (
          <div className="mt-5 pt-4 flex items-center gap-2 justify-center flex-wrap" style={{ borderTop: "1px solid #E2D9C2" }}>
            {selected === entry.s ? <Check size={18} color="#3E8159" /> : <X size={18} color="#B84239" />}
            <span className="text-sm font-semibold" style={{ color: selected === entry.s ? "#3E8159" : "#B84239" }}>{selected === entry.s ? "верно" : "неверно"}</span>
            <AccentWord entry={entry} size="text-base" />
          </div>
        )}
      </div>
    </>
  );
}

function PhraseQuestion({ entry, answered, selected, onPick }) {
  return (
    <>
      <p className="text-sm uppercase tracking-[0.14em] mb-3 font-semibold" style={{ color: FAINT }}>как правильно?</p>
      <div className="govorun-pop rounded-2xl p-6 mb-5" style={{ background: CREAM }}>
        <p className="text-lg leading-relaxed text-center mb-5" style={{ color: "#1E1B16" }}>
          {entry.p[0]}<span style={{ borderBottom: "2px dashed #C9BFA6", padding: "0 4px" }}>&nbsp;…&nbsp;</span>{entry.p[1]}
        </p>
        <div className="flex flex-col gap-2.5">
          {entry.opts.map((opt, i) => {
            const isCorrect = i === entry.c, isPicked = i === selected;
            let bg = "#EAE3D2", color = "#1E1B16", border = "1px solid transparent";
            if (answered) {
              if (isCorrect) { bg = "rgba(95,167,119,0.18)"; color = "#3E8159"; border = `1px solid ${GREEN}`; }
              else if (isPicked) { bg = "rgba(214,84,74,0.14)"; color = "#B84239"; border = `1px solid ${RED}`; }
            }
            return (
              <button key={i} onClick={() => onPick(i)} disabled={answered} className={`px-5 py-4 rounded-xl text-lg font-semibold text-left ${answered && isPicked && !isCorrect ? "govorun-shake" : ""}`} style={{ background: bg, color, border }}>{opt}</button>
            );
          })}
        </div>
        {answered && (
          <div className="mt-5 pt-4 flex items-start gap-2" style={{ borderTop: "1px solid #E2D9C2" }}>
            {selected === entry.c ? <Check size={18} color="#3E8159" style={{ marginTop: 2, flexShrink: 0 }} /> : <X size={18} color="#B84239" style={{ marginTop: 2, flexShrink: 0 }} />}
            <span className="text-sm" style={{ color: "#8A8371" }}>{entry.note}</span>
          </div>
        )}
      </div>
    </>
  );
}

/* ================================================================== */
/*  ОБО МНЕ                                                            */
/* ================================================================== */

